WITH promo_qty AS ( SELECT p.p_promo_id, p.p_promo_name, i.i_item_id, i.i_product_name, p.p_start_date_sk, p.p_end_date_sk, p.p_cost, i.i_current_price, p.p_response_target, ARRAY_AGG(DISTINCT w.w_state) AS promo_states, SUM(inv.inv_quantity_on_hand) AS promo_quantity FROM promotion p JOIN item i ON p.p_item_sk = i.i_item_sk JOIN inventory inv ON inv.inv_item_sk = i.i_item_sk AND inv.inv_date_sk BETWEEN p.p_start_date_sk AND p.p_end_date_sk JOIN warehouse w ON inv.inv_warehouse_sk = w.w_warehouse_sk WHERE w.w_country = 'US' GROUP BY p.p_promo_id, p.p_promo_name, i.i_item_id, i.i_product_name, p.p_start_date_sk, p.p_end_date_sk, p.p_cost, i.i_current_price, p.p_response_target ) SELECT p_promo_id, p_promo_name, i_item_id, i_product_name, p_start_date_sk, p_end_date_sk, p_cost, i_current_price, (i_current_price - p_cost) * 0.9 AS discounted_margin, promo_quantity, promo_states, CASE WHEN p_response_target >= 800 THEN 'Target >= 800' ELSE 'Target < 800' END AS target_category, ROW_NUMBER() OVER (ORDER BY promo_quantity DESC) AS qty_rank, AVG(promo_quantity) OVER () AS avg_promo_quantity FROM promo_qty WHERE promo_quantity > (SELECT AVG(promo_quantity) FROM promo_qty) ORDER BY qty_rank
